var MAX_STDIN_BYTES = 4 * 1024 * 1024;
async function readStdin() {
  const chunks = [];
  let size = 0;
  for await (const chunk of process.stdin) {
    const buf = chunk;
    size += buf.length;
    if (size > MAX_STDIN_BYTES) {
      return "";
    }
    chunks.push(buf);
  }
  return Buffer.concat(chunks).toString("utf8");
}
